   553  static int
   554  match(PCRE2_SPTR start_eptr, PCRE2_SPTR start_ecode, PCRE2_SIZE *ovector,
   555    uint16_t oveccount, uint16_t top_bracket, PCRE2_SIZE frame_size,
   556    match_block *mb)
   557  {
   558  /* Frame-handling variables */
   559
   560  heapframe *F;           /* Current frame pointer */
   561  heapframe *N = NULL;    /* Temporary frame pointers */
   562  heapframe *P = NULL;
   563  heapframe *assert_accept_frame;  /* For passing back the frame with captures */
   564  PCRE2_SIZE frame_copy_size;      /* Amount to copy when creating a new frame */
   565
