   567
   568  PCRE2_SPTR bracode;     /* Temp pointer to start of group */
   569  PCRE2_SIZE offset;      /* Used for group offsets */
   570  PCRE2_SIZE length;      /* Used for various length calculations */
   571
   572  int rrc;                /* Return from functions & backtracking "recursions" */
   573  #ifdef SUPPORT_UNICODE
   574  int proptype;           /* Type of character property */
   575  #endif
   576
   577  uint32_t i;             /* Used for local loops */
   578  uint32_t fc;            /* Character values */
   579  uint32_t number;        /* Used for group and other numbers */
   580  uint32_t reptype = 0;   /* Type of repetition (0 to avoid compiler warning) */
   581  uint32_t group_frame_type;  /* Specifies type for new group frames */
   582
   583  BOOL condition;         /* Used in conditional groups */
   584  BOOL cur_is_word;       /* Used in "word" tests */
   585  BOOL prev_is_word;      /* Used in "word" tests */
   586
   587  /* UTF flag */
   588
   589  #ifdef SUPPORT_UNICODE
