   600  /* Set up the first current frame at the start of the vector, and initialize
   601  fields that are not reset for new frames. */
   602
   603  F = mb->match_frames;
   604  Frdepth = 0;                        /* "Recursion" depth */
   605  Fcapture_last = 0;                  /* Number of most recent capture */
   606  Fcurrent_recurse = RECURSE_UNSET;   /* Not pattern recursing. */
   607  Fstart_match = Feptr = start_eptr;  /* Current data pointer and start match */
   608  Fmark = NULL;                       /* Most recent mark */
   609  Foffset_top = 0;                    /* End of captures within the frame */
   610  Flast_group_offset = PCRE2_UNSET;   /* Saved frame of most recent group */
   611  group_frame_type = 0;               /* Not a start of group frame */
