   624    {
   625    PCRE2_SIZE newsize = mb->frame_vector_size * 2;
   626    heapframe *new;
   627
   628    if ((newsize / 1024) > mb->heap_limit)
   629      {
   630      PCRE2_SIZE maxsize = ((mb->heap_limit * 1024)/frame_size) * frame_size;
   631      if (mb->frame_vector_size >= maxsize) return PCRE2_ERROR_HEAPLIMIT;
   632      newsize = maxsize;
   633      }
