   642    if (mb->match_frames != mb->stack_frames)
   643      mb->memctl.free(mb->match_frames, mb->memctl.memory_data);
   644    mb->match_frames = new;
   645    mb->match_frames_top = (heapframe *)((char *)mb->match_frames + newsize);
   646    mb->frame_vector_size = newsize;
