   648
   649  #ifdef DEBUG_SHOW_RMATCH
   650  fprintf(stderr, "++ RMATCH %2d frame=%d", Freturn_id, Frdepth + 1);
   651  if (group_frame_type != 0)
   652    {
   653    fprintf(stderr, " type=%x ", group_frame_type);
   654    switch (GF_IDMASK(group_frame_type))
   655      {
   656      case GF_CAPTURE:
   657      fprintf(stderr, "capture=%d", GF_DATAMASK(group_frame_type));
   658      break;
   659
   660      case GF_NOCAPTURE:
   661      fprintf(stderr, "nocapture op=%d", GF_DATAMASK(group_frame_type));
   662      break;
   663
   664      case GF_CONDASSERT:
   665      fprintf(stderr, "condassert op=%d", GF_DATAMASK(group_frame_type));
   666      break;
   667
   668      case GF_RECURSE:
   669      fprintf(stderr, "recurse=%d", GF_DATAMASK(group_frame_type));
   670      break;
   671
   672      default:
   673      fprintf(stderr, "*** unknown ***");
   674      break;
   675      }
   676    }
   677  fprintf(stderr, "\n");
   678  #endif
   679
   680  /* Copy those fields that must be copied into the new frame, increase the
   681  "recursion" depth (i.e. the new frame's index) and then make the new frame
   682  current. */
   683
   684  memcpy((char *)N + offsetof(heapframe, eptr),
   685         (char *)F + offsetof(heapframe, eptr),
   686         frame_copy_size);
   687
   688  N->rdepth = Frdepth + 1;
   689  F = N;
   690
   691  /* Carry on processing with a new frame. */
   692
   693  NEW_FRAME:
   694  Fgroup_frame_type = group_frame_type;
   695  Fecode = start_ecode;      /* Starting code pointer */
   696  Fback_frame = frame_size;  /* Default is go back one frame */
   697
   698  /* If this is a special type of group frame, remember its offset for quick
   699  access at the end of the group. If this is a recursion, set a new current
   700  recursion value. */
   701
   702  if (group_frame_type != 0)
   703    {
   704    Flast_group_offset = (char *)F - (char *)mb->match_frames;
   705    if (GF_IDMASK(group_frame_type) == GF_RECURSE)
   706      Fcurrent_recurse = GF_DATAMASK(group_frame_type);
   707    group_frame_type = 0;
   708    }
