   710
   711  /* ========================================================================= */
   712  /* This is the main processing loop. First check that we haven't recorded too
   713  many backtracks (search tree is too large), or that we haven't exceeded the
   714  recursive depth limit (used too many backtracking frames). If not, process the
   715  opcodes. */
   716
   717  if (mb->match_call_count++ >= mb->match_limit) return PCRE2_ERROR_MATCHLIMIT;
   718  if (Frdepth >= mb->match_limit_depth) return PCRE2_ERROR_DEPTHLIMIT;
