   720  for (;;)
   721    {
   722  #ifdef DEBUG_SHOW_OPS
   723  fprintf(stderr, "++ op=%d\n", *Fecode);
   724  #endif
   725
   726    Fop = *Fecode;
   727    switch(Fop)
   728      {
   729      /* ===================================================================== */
   730      /* Before OP_ACCEPT there may be any number of OP_CLOSE opcodes, to close
   731      any currently open capturing brackets. Unlike reaching the end of a group,
   732      where we know the starting frame is at the top of the chained frames, in
   733      this case we have to search back for the relevant frame in case other types
   734      of group that use chained frames have intervened. Multiple OP_CLOSEs always
   735      come innermost first, which matches the chain order. We can ignore this in
   736      a recursion, because captures are not passed out of recursions. */
