   739      if (Fcurrent_recurse == RECURSE_UNSET)
   740        {
   741        number = GET2(Fecode, 1);
   742        offset = Flast_group_offset;
   743        for(;;)
   744          {
   745          if (offset == PCRE2_UNSET) return PCRE2_ERROR_INTERNAL;
   746          N = (heapframe *)((char *)mb->match_frames + offset);
   747          P = (heapframe *)((char *)N - frame_size);
