   752        Fcapture_last = number;
   753        Fovector[offset] = P->eptr - mb->start_subject;
   754        Fovector[offset+1] = Feptr - mb->start_subject;
   755        if (offset >= Foffset_top) Foffset_top = offset + 2;
   756        }
   757      Fecode += PRIV(OP_lengths)[*Fecode];
   758      break;
   759
   760
   761      /* ===================================================================== */
   762      /* Real or forced end of the pattern, assertion, or recursion. In an
   763      assertion ACCEPT, update the last used pointer and remember the current
   764      frame so that the captures can be fished out of it. */
   765
   766      case OP_ASSERT_ACCEPT:
   767      if (Feptr > mb->last_used_ptr) mb->last_used_ptr = Feptr;
   768      assert_accept_frame = F;
   769      RRETURN(MATCH_ACCEPT);
   770
   771      /* If recursing, we have to find the most recent recursion. */
   772
   773      case OP_ACCEPT:
   774      case OP_END:
   775
   776      /* Handle end of a recursion. */
   777
   778      if (Fcurrent_recurse != RECURSE_UNSET)
   779        {
   780        offset = Flast_group_offset;
   781        for(;;)
   782          {
   783          if (offset == PCRE2_UNSET) return PCRE2_ERROR_INTERNAL;
   784          N = (heapframe *)((char *)mb->match_frames + offset);
   785          P = (heapframe *)((char *)N - frame_size);
   786          if (GF_IDMASK(N->group_frame_type) == GF_RECURSE) break;
   787          offset = P->last_group_offset;
   788          }
   789
   790        /* N is now the frame of the recursion; the previous frame is at the
   791        OP_RECURSE position. Go back there, copying the current subject position
   792        and mark, and move on past the OP_RECURSE. */
   793
   794        P->eptr = Feptr;
   795        P->mark = Fmark;
   796        F = P;
   797        Fecode += 1 + LINK_SIZE;
   798        continue;
   799        }
   800
   801      /* Not a recursion. Fail for an empty string match if either PCRE2_NOTEMPTY
   802      is set, or if PCRE2_NOTEMPTY_ATSTART is set and we have matched at the
   803      start of the subject. In both cases, backtracking will then try other
   804      alternatives, if any. */
   805
   806      if (Feptr == Fstart_match &&
   807           ((mb->moptions & PCRE2_NOTEMPTY) != 0 ||
   808             ((mb->moptions & PCRE2_NOTEMPTY_ATSTART) != 0 &&
   809               Fstart_match == mb->start_subject + mb->start_offset)))
   810        RRETURN(MATCH_NOMATCH);
