   812      /* Also fail if PCRE2_ENDANCHORED is set and the end of the match is not
   813      the end of the subject. After (*ACCEPT) we fail the entire match (at this
   814      position) but backtrack on reaching the end of the pattern. */
   815
   816      if (Feptr < mb->end_subject &&
   817          ((mb->moptions | mb->poptions) & PCRE2_ENDANCHORED) != 0)
   818        {
   819        if (Fop == OP_END) RRETURN(MATCH_NOMATCH);
   820        return MATCH_NOMATCH;
   821        }
   822
   823      /* We have a successful match of the whole pattern. Record the result and
   824      then do a direct return from the function. If there is space in the offset
   825      vector, set any pairs that follow the highest-numbered captured string but
   826      are less than the number of capturing groups in the pattern to PCRE2_UNSET.
   827      It is documented that this happens. "Gaps" are set to PCRE2_UNSET
   828      dynamically. It is only those at the end that need setting here. */
   829
   830      mb->end_match_ptr = Feptr;           /* Record where we ended */
   831      mb->end_offset_top = Foffset_top;    /* and how many extracts were taken */
   832      mb->mark = Fmark;                    /* and the last success mark */
   833      if (Feptr > mb->last_used_ptr) mb->last_used_ptr = Feptr;
   834
   835      ovector[0] = Fstart_match - mb->start_subject;
   836      ovector[1] = Feptr - mb->start_subject;
   837
   838      /* Set i to the smaller of the sizes of the external and frame ovectors. */
   839
   840      i = 2 * ((top_bracket + 1 > oveccount)? oveccount : top_bracket + 1);
   841      memcpy(ovector + 2, Fovector, (i - 2) * sizeof(PCRE2_SIZE));
   842      while (--i >= Foffset_top + 2) ovector[i] = PCRE2_UNSET;
   843      return MATCH_MATCH;  /* Note: NOT RRETURN */
   844
   845
   846      /*===================================================================== */
   847      /* Match any single character type except newline; have to take care with
   848      CRLF newlines and partial matching. */
   849
   850      case OP_ANY:
   851      if (IS_NEWLINE(Feptr)) RRETURN(MATCH_NOMATCH);
   852      if (mb->partial != 0 &&
   853          Feptr == mb->end_subject - 1 &&
   854          NLBLOCK->nltype == NLTYPE_FIXED &&
   855          NLBLOCK->nllen == 2 &&
   856          UCHAR21TEST(Feptr) == NLBLOCK->nl[0])
