   858        mb->hitend = TRUE;
   859        if (mb->partial > 1) return PCRE2_ERROR_PARTIAL;
   860        }
   861      /* Fall through */
   862
   863      /* Match any single character whatsoever. */
   864
   865      case OP_ALLANY:
   866      if (Feptr >= mb->end_subject)  /* DO NOT merge the Feptr++ here; it must */
   867        {                            /* not be updated before SCHECK_PARTIAL. */
   868        SCHECK_PARTIAL();
   869        RRETURN(MATCH_NOMATCH);
   870        }
   871      Feptr++;
   872  #ifdef SUPPORT_UNICODE
   873      if (utf) ACROSSCHAR(Feptr < mb->end_subject, *Feptr, Feptr++);
   874  #endif
   875      Fecode++;
   876      break;
   877
   878
   879      /* ===================================================================== */
   880      /* Match a single code unit, even in UTF mode. This opcode really does
  6000
  6001  Returns:          > 0 => success; value is the number of ovector pairs filled
  6002                    = 0 => success, but ovector is not big enough
  6003                     -1 => failed to match (PCRE2_ERROR_NOMATCH)
  6004                     -2 => partial match (PCRE2_ERROR_PARTIAL)
