  6102  /* Partial matching and PCRE2_ENDANCHORED are currently not allowed at the same
  6103  time. */
  6104
  6105  if (mb->partial != 0 &&
  6106     ((re->overall_options | options) & PCRE2_ENDANCHORED) != 0)
  6107    return PCRE2_ERROR_BADOPTION;
