  6109  /* Check a UTF string for validity if required. For 8-bit and 16-bit strings,
  6110  we must also check that a starting offset does not point into the middle of a
  6111  multiunit character. We check only the portion of the subject that is going to
  6112  be inspected during matching - from the offset minus the maximum back reference
  6113  to the given length. This saves time when a small part of a large subject is
  6114  being matched by the use of a starting offset. Note that the maximum lookbehind
  6115  is a number of characters, not code units. */
  6116
  6117  #ifdef SUPPORT_UNICODE
  6118  if (utf && (options & PCRE2_NO_UTF_CHECK) == 0)
  6119    {
  6120    PCRE2_SPTR check_subject = start_match;  /* start_match includes offset */
  6121
  6122    if (start_offset > 0)
  6123      {
  6124  #if PCRE2_CODE_UNIT_WIDTH != 32
  6125      unsigned int i;
  6126      if (start_match < end_subject && NOT_FIRSTCU(*start_match))
  6127        return PCRE2_ERROR_BADUTFOFFSET;
  6128      for (i = re->max_lookbehind; i > 0 && check_subject > subject; i--)
  6129        {
  6130        check_subject--;
  6131        while (check_subject > subject &&
  6132  #if PCRE2_CODE_UNIT_WIDTH == 8
  6133        (*check_subject & 0xc0) == 0x80)
  6134  #else  /* 16-bit */
  6135        (*check_subject & 0xfc00) == 0xdc00)
  6136  #endif /* PCRE2_CODE_UNIT_WIDTH == 8 */
  6137          check_subject--;
  6138        }
