  6141      we cannot just subtract the lookbehind and then compare pointers, because
  6142      a very large lookbehind could create an invalid pointer. */
  6143
  6144      if (start_offset >= re->max_lookbehind)
  6145        check_subject -= re->max_lookbehind;
  6146      else
  6147        check_subject = subject;
  6148  #endif  /* PCRE2_CODE_UNIT_WIDTH != 32 */
  6149      }
  6150
