  6152    offset to be an absolute offset in the whole string. */
  6153
  6154    match_data->rc = PRIV(valid_utf)(check_subject,
  6155      length - (check_subject - subject), &(match_data->startchar));
  6156    if (match_data->rc != 0)
  6157      {
  6158      match_data->startchar += check_subject - subject;
  6159      return match_data->rc;
  6160      }
  6161    }
  6162  #endif  /* SUPPORT_UNICODE */
  6163
  6164  /* It is an error to set an offset limit without setting the flag at compile
  6165  time. */
  6166
  6167  if (mcontext != NULL && mcontext->offset_limit != PCRE2_UNSET &&
  6168       (re->overall_options & PCRE2_USE_OFFSET_LIMIT) == 0)
  6169    return PCRE2_ERROR_BADOFFSETLIMIT;
