  6173  compile time for the JIT code to be usable. Fallback to the normal code path if
  6174  an unsupported option is set or if JIT returns BADOPTION (which means that the
  6175  selected normal or partial matching mode was not compiled). */
  6176
  6177  #ifdef SUPPORT_JIT
  6178  if (re->executable_jit != NULL && (options & ~PUBLIC_JIT_MATCH_OPTIONS) == 0)
  6179    {
  6180    rc = pcre2_jit_match(code, subject, length, start_offset, options,
